export async function getSpotPrices() {
  try {
    const start = berlinDatum(0);
    const ende = berlinDatum(2);
    const j = await holeJson(`${EC}/price?bzn=DE-LU&start=${start}&end=${ende}`, 900);
    const punkte = (j.unix_seconds || [])
